SELECT m.*,
p.status AS participantStatus,
CASE WHEN f.favorite_id IS
NULL THEN 0 ELSE 1 END AS favorite
FROM personal_match_participant p
JOIN personal_match m 
ON m.personal_match_id = p.personal_match_id
LEFT JOIN favorite f
ON f.match_id = m.personal_match_id
AND f.user_id = #{userId}
AND f.match_type = 'Personal'
WHERE p.user_id = #{userId}
AND p.status IN ('결제완료')

	AND m.sport = #{sport}


	AND m.status = #{status}

 AND m.match_date >= #{startDate} 
 AND m.match_date <= #{endDate} 
ORDER BY m.match_date, m.personal_match_id
LIMIT #{size} OFFSET
#{offset}

SELECT COUNT(*) FROM personal_match_participant p JOIN personal_match m ON m.personal_match_id = p.personal_match_id WHERE p.user_id = #{userId} AND p.status IN ('결제완료')
AND m.match_date >= STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d') AND m.match_date < DATE_ADD(STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH)
AND m.sport = #{sport}
AND m.status = #{status}

SELECT m.*,
CASE WHEN f.favorite_id IS NULL THEN 0 ELSE 1 END AS
favorite
FROM personal_match m
LEFT JOIN favorite f
ON f.match_id =
m.personal_match_id
AND f.user_id = #{userId}
AND f.match_type =
'Personal'
WHERE m.user_id = #{userId}
AND m.deleted = '0'

	AND m.sport = #{sport}


	AND m.status = #{status}

 AND m.match_date >= #{startDate} 
 AND m.match_date <= #{endDate} 
ORDER BY m.match_date DESC, m.personal_match_id DESC
LIMIT #{size}
OFFSET #{offset}

SELECT COUNT(*) FROM personal_match m WHERE m.user_id = #{userId} AND m.deleted = 0
AND m.match_date >= STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d') AND m.match_date < DATE_ADD(STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH)
AND m.sport = #{sport}
AND m.status = #{status}

SELECT m.*
FROM personal_match m
WHERE m.user_id = #{userId}
AND m.deleted = 0

	AND m.match_date >= STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d')
	AND m.match_date < DATE_ADD(STR_TO_DATE(CONCAT(#{month}, '-01'),
	'%Y-%m-%d'), INTERVAL 1 MONTH)


	AND m.sport = #{sport}


	AND m.status = #{status}

ORDER BY m.match_date DESC, m.personal_match_id DESC
LIMIT #{size} OFFSET #{offset}

SELECT DISTINCT DATE_FORMAT(m.match_date, '%Y-%m-%d')
FROM personal_match_participant p
JOIN personal_match m
ON m.personal_match_id = p.personal_match_id
WHERE p.user_id = #{userId}
AND p.status IN ('결제완료')
 AND m.sport = #{sport} 
 AND m.status = #{status}

